pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool shouldPause) public {
        vm.assume(shouldPause == true || shouldPause == false);
        if (shouldPause) {
            vm.prank(c.owner());
            c.pause();
        }
        bool transferReverts;
        try c.paused() returns (bool pausing) {
            // _update reverts with EnforcedPause when paused() returns true
            // we check whether a transfer reverts to determine the actual pausing state
            address random = makeAddr("random");
            vm.deal(random, 1 ether);
            vm.prank(random);
            try c.safeTransferFrom(address(0), address(1), 0, 1, "") {} catch {
                transferReverts = true;
            }
            // Rule: paused() should return true iff a transfer (which calls _update) reverts due to pause
            assertTrue(pausing == transferReverts);
        } catch {
            // If paused() itself reverts something is very wrong; we just fail
            assertTrue(false);
        }
    }
}

