pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp) public {
        vm.warp(timestamp);
        bool pausedBefore = c.paused();
        if (!pausedBefore) {
            // try to trigger internal pause
            try c.pause() { pausedBefore = c.paused(); } catch { }
        }
        // now pausedBefore is the paused state as seen by the public getter
        // we try a transfer that should be blocked if pausedBefore is true
        bool transferReverted = false;
        try c.safeTransferFrom(address(this), address(1), 0, 1, "") { } catch { transferReverted = true; }
        // rule: the transfer should revert exactly when paused() returns true
        assertTrue(transferReverted == pausedBefore);
    }
}

