pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool shouldPause) public {
        // 1. Set up the contract's internal pause state by pausing or unpausing as the fuzzer chooses.
        //    We use the fact that the owner can call pause() and unPause().
        //    To exercise the internal state, we need to be the owner.
        address owner = address(0x123);
        vm.deal(owner, 0);
        vm.prank(owner);
        if (shouldPause) {
            c.pause();
        } else {
            c.unPause();
        }

        // 2. Read the paused state through the public view function.
        bool actualPaused = c.paused();

        // 3. General rule: the paused() return value must match the actual paused state that we set.
        //    The reference contract satisfies: actualPaused == shouldPause.
        //    The mutant returns true always, so when shouldPause is false, the assertion fails.
        assertTrue(actualPaused == shouldPause, "paused() must return the correct internal state");
    }
}

