        c.initialize(1, 1, "verification", address(0x1000));
    }
    function testFuzz_property(uint256 tokenId) public {
        vm.assume(tokenId != type(uint256).max); // avoid any potential slot collision edge, keep wide
        // Get royalties configuration for the fuzzed token id
        ICreatorRoyaltiesControl.RoyaltyConfiguration memory config = c.getRoyalties(tokenId);
        // The reference contract should return royaltyBPS = 500 (the default) when no specific royalty is set.
