pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 tokenId, address royaltyRecipient, uint32 customBps) public {
        vm.assume(royaltyRecipient != address(0));
        vm.assume(customBps <= 10000);
        // initialize the royalty module via the parent contract's internal mechanism.
        // Because initializeRoyalties is internal we call it indirectly by deploying
        // the contract through a proxy? No, we only have c. The only way to set the
        // initialization flag and royaltyRecipient is through the contract's own
        // `initialize()` function which is called with an initialOwner.
        // We rely on the fuzzer to call the exposed surface only.
        // The default royaltyRecipient is set during `initializeRoyalties` inside
        // `initialize`. Without calling `initialize`, getRoyalties will revert with
        // NotInitialized, which is not a difference we want to test.
        // We need the contract initialized: call `initialize` with valid params.
        // We use a dummy credChainId, credId, verificationType, and protocolFeeDestination.
        // Call it once. If already initialized it will revert, so we catch.
        try c.initialize(1, 1, "test", royaltyRecipient) {} catch {}
        // If initialization succeeded, getRoyalties will not revert for NotInitialized.
        // Now query getRoyalties for the fuzzed tokenId.
        // It may revert if still NotInitialized; we catch that.
        bool ok;
        ICreatorRoyaltiesControl.RoyaltyConfiguration memory config;
        try c.getRoyalties(tokenId) returns (ICreatorRoyaltiesControl.RoyaltyConfiguration memory result) {
            ok = true;
            config = result;
        } catch {
            ok = false;
        }
        // If initialized and getRoyalties didn't revert, the returned royaltyBPS must
        // equal the reference default of 500 when no custom royalty is set for this token.
        // The bug changes the default to 1000.
        // The rule: If the call succeeds, the returned royaltyBPS must be 500.
        // (We cannot check custom royalties because the fuzzer does not set them,
        // so the returned value must be the default).
        // To avoid the obvious always-false when custom is set, we rely on the fact
        // that custom royalties can only be set by updateRoyalties, which requires
        // an existing artId linked to this token. In this test, no art is created,
        // so royalties[tokenId] is empty and royaltyRecipient is address(0),
        // forcing the default path.
        // But updateRoyalties could have been called? The test does not call it.
        // So if initialized, the default should be 500.
        if (ok) {
            assertEq(config.royaltyBPS, 500);
        }
    }
}

interface ICreatorRoyaltiesControl {
    struct RoyaltyConfiguration {
        uint32 royaltyBPS;
        address royaltyRecipient;
    }
    function getRoyalties(uint256 tokenId) external view returns (RoyaltyConfiguration memory);
}

